values ('QUEST_NEUTRAL_STORY_001', 'The Weight of Peace', 'story', 'B', 'GALACTIC_CUSTODIANS', 'NEXUS_CORE', 'Arbiter Lorn Kael has received intelligence of illegal weapon stockpiling near the border between two faction territories. (Location: Nexus Core, Arbiter Lorn Kael) A third party is believed to be arming both sides to provoke conflict. Investigate the weapons cache and report your findings to the Arbiter before a spark ignites a war.', '{"npc_id": "NPC_NEXUS_QUESTGIVER_ARBITER", "name": "Arbiter Lorn Kael", "location": "Pax Nexus — The Conclave Hall"}'::jsonb, '{"min_level": 10, "reputation_required": 0, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "travel", "target": "NEXUS_CORE", "count": 1, "description": "Visit Arbiter Lorn Kael in the Conclave Hall to receive mission briefing (Travel to: Nexus Core)"}, {"type": "kill", "target": "ROGUE_ARMS_DEALER", "count": 5, "description": "Neutralize {count} rogue arms dealers near the contested border"}, {"type": "collect", "target": "ILLEGAL_WEAPON_CACHE", "count": 3, "description": "Recover 3 illegal weapon caches"}, {"type": "interact", "target": "NPC_NEXUS_QUESTGIVER_ARBITER", "count": 1, "description": "Return evidence to Arbiter Lorn Kael (Arbiter Lorn Kael at Pax Nexus — The Conclave Hall)"}]'::jsonb, '{"exp": 800, "currency": 0, "crd": 350, "reputation": 30, "items": [{"item_id": "CUSTODIAN_BADGE_BRONZE", "quantity": 1}]}'::jsonb, false, false, 'QUEST_NEUTRAL_STORY_002', false, NULL, NULL, NULL, 'quest_neutral.json', 1)
