values ('QUEST_NEUTRAL_STORY_003', 'The Conclave''s Verdict', 'story', 'S', 'GALACTIC_CUSTODIANS', 'NEXUS_CORE', 'The intelligence gathered reveals an existential threat: a rogue Custodian officer is orchestrating the shadow organization, using faction conflict as cover for acquiring planet-killer weapon components. (Location: Nexus Core, Ambassador Vael Drosian) Ambassador Vael must be briefed, and the threat neutralized before the next Conclave session. This is a multi-stage raid-level operation.', '{"npc_id": "NPC_NEXUS_DIPLOMAT_VAEL", "name": "Ambassador Vael Drosian", "location": "Pax Nexus — The Diplomat''s Quarter"}'::jsonb, '{"min_level": 40, "reputation_required": 200, "required_quests": ["QUEST_NEUTRAL_STORY_002"], "party_required": true, "raid_size": 4}'::jsonb, '[{"type": "travel", "target": "ROGUE_CUSTODIAN_FORTRESS", "count": 1, "description": "Breach the rogue Custodian''s hidden fortress"}, {"type": "destroy", "target": "WEAPON_COMPONENT_STORAGE", "count": 6, "description": "Destroy {count} planet-killer weapon component storage pods"}, {"type": "kill", "target": "ROGUE_CUSTODIAN_COMMANDER", "count": 1, "description": "Defeat the rogue Custodian Commander — a former Guardian-class Dreadnought captain"}, {"type": "interact", "target": "NPC_NEXUS_DIPLOMAT_VAEL", "count": 1, "description": "Return to Ambassador Vael with proof of neutralization (Ambassador Vael Drosian at Pax Nexus — The Diplomat''s Quarter)"}]'::jsonb, '{"exp": 8000, "currency": 0, "crd": 3500, "reputation": 200, "items": [{"item_id": "CUSTODIAN_BADGE_GOLD", "quantity": 1}, {"item_id": "PACT_KEEPER_INSIGNIA", "quantity": 1}, {"item_id": "SENTINEL_ELITE_ARMOR_CHEST", "quantity": 1}]}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 3)
