values ('QUEST_NEUTRAL_SIDE_002', 'The Chronicler''s Lost Page', 'side', 'A', 'NEUTRAL', 'NEXUS_CORE', 'The Chronicler has detected a missing fragment of the Galactic Archive — a page describing an ancient faction conflict that was deliberately erased. (Location: Nexus Core, The Chronicler) Someone doesn''t want this history known. Recover it from a deep-tier region before it''s destroyed.', '{"npc_id": "NPC_NEXUS_INFO_CHRONICLER", "name": "The Chronicler", "location": "Pax Nexus — The Archive Spire"}'::jsonb, '{"min_level": 25, "reputation_required": 50, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "travel", "target": "SECRET_VAULT_REGION", "count": 1, "description": "Reach the hidden archive vault in the deep-tier region"}, {"type": "scan", "target": "ARCHIVE_FRAGMENT_READER", "count": 3, "description": "Scan {count} archive fragment readers to locate the lost page"}, {"type": "kill", "target": 5166, "count": 4, "description": "Defeat {count} automatons guarding the vault", "target_code": "GRID_DEFENDER"}, {"type": "collect", "target": "archive_scroll", "count": 1, "description": "Retrieve the lost archive page"}, {"type": "interact", "target": "NPC_NEXUS_INFO_CHRONICLER", "count": 1, "description": "Return the page to The Chronicler (The Chronicler at Pax Nexus — The Archive Spire)"}]'::jsonb, '{"exp": 1800, "currency": 0, "crd": 700, "reputation": 50, "items": [{"item_id": "mat_quantum_lens", "quantity": 1}, {"item_id": "ancient_data_slate", "quantity": 1}]}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 6)
