values ('QUEST_NEUTRAL_SIDE_003', 'Vulkan''s Special Order', 'side', 'B', 'NEUTRAL', 'NEXUS_CORE', 'Master Vulkan has been commissioned to forge a legendary weapon, but requires materials that can only be found in high-danger regions controlled by specific factions. (Location: Nexus Core, Vulkan Dross) Gather the materials — from any source.', '{"npc_id": "NPC_NEXUS_BLACKSMITH_VULKAN", "name": "Vulkan Dross", "location": "Pax Nexus — The Crucible"}'::jsonb, '{"min_level": 30, "reputation_required": 0, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "collect", "target": "salvaged_alloy_fragment", "count": 10, "description": "Collect 10 Iron Hegemon Alloy Shards (from Iron Hegemony regions)"}, {"type": "collect", "target": "crystal_core", "count": 5, "description": "Collect 5 Arcane Crystal Cores (from Arcanum Seeker regions)"}, {"type": "collect", "target": "mat_iron_ore", "count": 8, "description": "Collect 8 Starforged Stellar Ore (from Starforged Legion regions)"}, {"type": "interact", "target": "NPC_NEXUS_BLACKSMITH_VULKAN", "count": 1, "description": "Deliver materials to Vulkan Dross (Vulkan Dross at Pax Nexus — The Crucible)"}]'::jsonb, '{"exp": 1200, "currency": 0, "crd": 500, "reputation": 25, "items": [{"item_id": "ingot_cache", "quantity": 3}]}'::jsonb, true, false, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 7)
