values ('QUEST_NEUTRAL_DAILY_002', 'Market Stabilization', 'daily', 'B', 'NEUTRAL', 'NEXUS_CORE', 'The AMA needs item material samples from various regions to calculate accurate resource production indices for exchange rate computation. (Location: Nexus Core, NEXON AMA-7) Gather materials from different zone tiers.', '{"npc_id": "NPC_NEXUS_BANKER_AMA7", "name": "NEXON AMA-7", "location": "Pax Nexus — The AMA Exchange Hub"}'::jsonb, '{"min_level": 10, "reputation_required": 0, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "collect", "target": "scrap_metal", "count": 20, "description": "Collect 20 material resource samples from any region (any item material counts)"}]'::jsonb, '{"exp": 400, "currency": 0, "crd": 150, "reputation": 12, "items": []}'::jsonb, true, true, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 10)
