values ('QUEST_NEUTRAL_DAILY_003', 'The Ghost''s Errand', 'daily', 'A', 'NEUTRAL', 'NEXUS_CORE', 'Ghost needs a package delivered to a contact in a high-danger region. (Location: Nexus Core, Revan ''Ghost'' Mox) He assures you the contents are legal. He always says that. The contact will pay upon delivery — which means you''ll need to handle anything that tries to stop you.', '{"npc_id": "NPC_NEXUS_QUESTGIVER_SMUGGLER", "name": "Revan ''Ghost'' Mox", "location": "Pax Nexus — The Shadow Bazaar"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "travel", "target": "HIGH_ZONE_DELIVERY_POINT", "count": 1, "description": "Reach the delivery point in the high-danger region"}, {"type": "kill", "target": 5162, "count": 6, "description": "Eliminate {count} interceptors who ambush you during delivery", "target_code": "DELTA_ASSAULT_DRONE"}, {"type": "interact", "target": "npc_shady_smuggler", "count": 1, "description": "Complete the delivery with Ghost''s contact"}]'::jsonb, '{"exp": 600, "currency": 0, "crd": 280, "reputation": 0, "items": [{"item_id": "smugglers_cache", "quantity": 1}]}'::jsonb, true, true, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 11)
